CREATE TABLE tenants(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','researcher')), verified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE sessions(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE domains(id TEXT PRIMARY KEY, domain TEXT NOT NULL UNIQUE, normalized_json TEXT NOT NULL);
CREATE TABLE listings(id TEXT PRIMARY KEY, domain_id TEXT NOT NULL REFERENCES domains(id), tenant_id TEXT NOT NULL REFERENCES tenants(id), source TEXT NOT NULL, external_id TEXT NOT NULL, dataset TEXT NOT NULL CHECK(dataset IN ('fixture','manual','live')), public_allowed INTEGER NOT NULL DEFAULT 0, notifications_allowed INTEGER NOT NULL DEFAULT 0, license_ref TEXT NOT NULL, record_json TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(domain_id,tenant_id,source,external_id,dataset));
CREATE INDEX listings_scope ON listings(dataset,tenant_id,public_allowed);
CREATE TABLE observations(id TEXT PRIMARY KEY, listing_id TEXT NOT NULL REFERENCES listings(id), fingerprint TEXT NOT NULL, raw_json TEXT NOT NULL, observed_at TEXT NOT NULL, UNIQUE(listing_id,fingerprint));
CREATE INDEX observations_latest ON observations(listing_id,observed_at DESC);
CREATE TABLE rules(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, tenant_id TEXT NOT NULL REFERENCES tenants(id), version INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, rule_json TEXT NOT NULL, created_at TEXT NOT NULL, last_evaluated_at TEXT);
CREATE INDEX rules_scope ON rules(user_id,tenant_id);
CREATE TABLE rule_versions(rule_id TEXT NOT NULL REFERENCES rules(id) ON DELETE CASCADE, version INTEGER NOT NULL, rule_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(rule_id,version));
CREATE TABLE watchlist(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, listing_id TEXT NOT NULL REFERENCES listings(id), created_at TEXT NOT NULL, PRIMARY KEY(user_id,listing_id));
CREATE TABLE link_codes(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE telegram_links(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, destination_hash TEXT NOT NULL UNIQUE, encrypted_destination TEXT NOT NULL, linked_at TEXT NOT NULL);
CREATE TABLE delivery_events(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, rule_id TEXT NOT NULL REFERENCES rules(id) ON DELETE CASCADE, observation_id TEXT NOT NULL REFERENCES observations(id), status TEXT NOT NULL CHECK(status IN ('pending','sending','sent','failed','uncertain','cancelled')), payload TEXT NOT NULL, created_at TEXT NOT NULL, sent_at TEXT, attempts INTEGER NOT NULL DEFAULT 0, UNIQUE(user_id,rule_id,observation_id));
CREATE INDEX deliveries_scope ON delivery_events(user_id,created_at,status);
CREATE TABLE jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','done','dead')), attempts INTEGER NOT NULL DEFAULT 0, available_at INTEGER NOT NULL, lease_until INTEGER, checkpoint TEXT, last_error TEXT, created_at TEXT NOT NULL);
CREATE INDEX jobs_queue ON jobs(state,available_at,lease_until);
CREATE TABLE request_ledger(id TEXT PRIMARY KEY, provider TEXT NOT NULL, created_at TEXT NOT NULL, cost_cents INTEGER NOT NULL CHECK(cost_cents>=0));
CREATE INDEX request_budget ON request_ledger(provider,created_at);
CREATE TABLE audit_events(id TEXT PRIMARY KEY, user_id TEXT, tenant_id TEXT, action TEXT NOT NULL, created_at TEXT NOT NULL, details TEXT NOT NULL);
